type Factory<T> = () => T;
const registry = new Map<string, Factory<unknown>>();

export function register<T>(name: string, factory: Factory<T>): void {
  if (registry.has(name)) throw new Error(`duplicate registration: ${name}`);
  registry.set(name, factory as Factory<unknown>);
}

export function lookup<T>(name: string): T {
  const factory = registry.get(name);
  if (!factory) throw new Error(`unknown service: ${name}`);
  return factory() as T;
}

