const registry = new Map<string, unknown>();

function Registered(name: string) {
  return function <T extends new (...args: any[]) => unknown>(
    target: T, context: ClassDecoratorContext<T>) {
    if (registry.has(name)) throw new Error(`duplicate: ${name}`);
    registry.set(name, target);
  };
}

